-- PAVO Club schema for a NEW Supabase project.
-- If you already ran the PAVO SQL in your project, do not rerun this file blindly.
-- It documents the expected tables. Browser access is controlled by RLS.
create extension if not exists pgcrypto;
create table if not exists public.site_settings(key text primary key,value jsonb not null default '{}'::jsonb,is_public boolean not null default false,updated_at timestamptz not null default now());
create table if not exists public.players(id uuid primary key default gen_random_uuid(),full_name_ar text,full_name_en text,slug text unique not null,shirt_number integer,position text,nationality_ar text,nationality_en text,birth_date date,height_cm integer,preferred_foot text,photo_path text,bio_ar text,bio_en text,appearances integer not null default 0,goals integer not null default 0,assists integer not null default 0,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.staff(id uuid primary key default gen_random_uuid(),full_name_ar text,full_name_en text,role_ar text,role_en text,photo_path text,bio_ar text,bio_en text,sort_order integer not null default 0,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.matches(id uuid primary key default gen_random_uuid(),opponent_name_ar text,opponent_name_en text,opponent_logo_path text,competition_ar text,competition_en text,venue_ar text,venue_en text,kickoff_at timestamptz,status text not null default 'scheduled' check(status in('scheduled','live','finished','postponed','cancelled')),home_score integer,away_score integer,round_label_ar text,round_label_en text,report_ar text,report_en text,is_published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.match_events(id uuid primary key default gen_random_uuid(),match_id uuid not null references public.matches(id) on delete cascade,player_id uuid references public.players(id) on delete set null,minute integer,event_type text not null check(event_type in('goal','own_goal','yellow_card','red_card','substitution','penalty','other')),description_ar text,description_en text,related_player_id uuid references public.players(id) on delete set null,created_at timestamptz not null default now());
create table if not exists public.lineups(id uuid primary key default gen_random_uuid(),match_id uuid references public.matches(id) on delete set null,name_ar text,name_en text,formation_code text not null default '4-3-3',status text not null default 'draft' check(status in('draft','published','archived')),is_current boolean not null default false,notes_ar text,notes_en text,published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.lineup_players(id uuid primary key default gen_random_uuid(),lineup_id uuid not null references public.lineups(id) on delete cascade,player_id uuid not null references public.players(id) on delete restrict,x_position numeric not null check(x_position between 0 and 100),y_position numeric not null check(y_position between 0 and 100),tactical_position text,is_starter boolean not null default true,is_captain boolean not null default false,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(lineup_id,player_id));
create table if not exists public.news(id uuid primary key default gen_random_uuid(),title_ar text,title_en text,slug text unique not null,summary_ar text,summary_en text,content_ar text,content_en text,cover_path text,category_ar text,category_en text,status text not null default 'draft' check(status in('draft','published','archived')),published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.media(id uuid primary key default gen_random_uuid(),file_path text unique not null,file_name text,content_type text,file_size bigint,alt_ar text,alt_en text,is_public boolean not null default true,uploaded_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create table if not exists public.admin_profiles(user_id uuid primary key references auth.users(id) on delete cascade,display_name text,role text not null default 'editor' check(role in('super_admin','admin','editor')),is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create or replace function public.set_updated_at() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end;$$;
do $$declare t text;begin foreach t in array array['site_settings','players','staff','matches','lineups','lineup_players','news','admin_profiles'] loop execute format('drop trigger if exists set_updated_at on public.%I',t);execute format('create trigger set_updated_at before update on public.%I for each row execute function public.set_updated_at()',t);end loop;end$$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.admin_profiles ap where ap.user_id=auth.uid() and ap.is_active=true and ap.role in('super_admin','admin'));$$;
create or replace function public.is_editorial_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.admin_profiles ap where ap.user_id=auth.uid() and ap.is_active=true and ap.role in('super_admin','admin','editor'));$$;
-- Enable RLS on all tables. Review and apply matching policies from the Supabase SQL editor.
alter table public.site_settings enable row level security;alter table public.players enable row level security;alter table public.staff enable row level security;alter table public.matches enable row level security;alter table public.match_events enable row level security;alter table public.lineups enable row level security;alter table public.lineup_players enable row level security;alter table public.news enable row level security;alter table public.media enable row level security;alter table public.admin_profiles enable row level security;
-- Public read policies
 drop policy if exists "Public read site settings" on public.site_settings;create policy "Public read site settings" on public.site_settings for select using(is_public=true);
 drop policy if exists "Public read active players" on public.players;create policy "Public read active players" on public.players for select using(is_active=true);
 drop policy if exists "Public read active staff" on public.staff;create policy "Public read active staff" on public.staff for select using(is_active=true);
 drop policy if exists "Public read published matches" on public.matches;create policy "Public read published matches" on public.matches for select using(is_published=true);
 drop policy if exists "Public read events of published matches" on public.match_events;create policy "Public read events of published matches" on public.match_events for select using(exists(select 1 from public.matches m where m.id=match_id and m.is_published=true));
 drop policy if exists "Public read published lineups" on public.lineups;create policy "Public read published lineups" on public.lineups for select using(status='published' and (match_id is null or exists(select 1 from public.matches m where m.id=match_id and m.is_published=true)));
 drop policy if exists "Public read published lineup players" on public.lineup_players;create policy "Public read published lineup players" on public.lineup_players for select using(exists(select 1 from public.lineups l where l.id=lineup_id and l.status='published' and (l.match_id is null or exists(select 1 from public.matches m where m.id=l.match_id and m.is_published=true))));
 drop policy if exists "Public read published news" on public.news;create policy "Public read published news" on public.news for select using(status='published');
 drop policy if exists "Public read public media" on public.media;create policy "Public read public media" on public.media for select using(is_public=true);
-- Admin management policies for tables. Restrict admin-profile changes separately in production.
do $$declare t text;begin foreach t in array array['site_settings','players','staff','matches','match_events','lineups','lineup_players','news','media'] loop execute format('drop policy if exists "Admins manage %s" on public.%I',t,t);execute format('create policy "Admins manage %s" on public.%I for all to authenticated using(public.is_admin()) with check(public.is_admin())',t,t);end loop;end$$;
drop policy if exists "Admins read admin profiles" on public.admin_profiles;create policy "Admins read admin profiles" on public.admin_profiles for select to authenticated using(public.is_admin() or user_id=auth.uid());
drop policy if exists "Super admins manage admin profiles" on public.admin_profiles;create policy "Super admins manage admin profiles" on public.admin_profiles for all to authenticated using(exists(select 1 from public.admin_profiles ap where ap.user_id=auth.uid() and ap.is_active and ap.role='super_admin')) with check(exists(select 1 from public.admin_profiles ap where ap.user_id=auth.uid() and ap.is_active and ap.role='super_admin'));
-- Storage: create a PUBLIC bucket named pavo-media in Dashboard > Storage.
-- Add a public SELECT policy for that bucket; allow INSERT/UPDATE/DELETE only for authenticated admins.
